-- Jeu de LecteurJonctions et EcrivainJonctions (« Jonction d'instances », PROC_JOIN), lot 4 du plan « RIG v3 100 % fonctionnel »
-- (plan-676a4b19). Identifiants 14xx xxx. Tables aux types de RIG_DEV (INFORMATION_SCHEMA.COLUMNS de SQL-DEV\DEV, lu le
-- 26/11/2026), creees si absentes, completees sinon ; lignes par sp_executesql.
-- Ce jeu pose aussi les INSTANCES du lot 4 que lisent « Liens entre PC » (PROC_XLIEN) et « Supprimer une instance »
-- (PROC_XXAFF) : roles 1990xxxxxx, ils se rangent apres ceux des autres jeux (role decroissant). Les codes PC14 (JRPC) et OP14
-- (JROP) sont des types de « Instance judiciaire » : ces instances sont aussi dans PROC_MJUD.attendu et PROC_MJUD.gestes.
IF OBJECT_ID(N'v2.INSTANCE') IS NULL
    CREATE TABLE v2.INSTANCE (INSTN_ID_INSTN int NOT NULL PRIMARY KEY, INSTN_NUM_ROLE varchar(11) NULL, INSTN_NOM_COURANT varchar(250) NULL);
IF COL_LENGTH('v2.INSTANCE', 'INSTN_CODE_AFFAIRE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_CODE_AFFAIRE varchar(10) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_NATURE_AFFAIRE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_NATURE_AFFAIRE varchar(10) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_CODE_ACTE_PROCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_CODE_ACTE_PROCE varchar(3) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_ACTE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_ACTE datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_ENROLEMENT') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_ENROLEMENT datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_SAISINE_GREFFE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_SAISINE_GREFFE datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_PRCLL') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_PRCLL int NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_PREVE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_PREVE int NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_INSTN_INSTANCE_PRINCIPA') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_INSTN_INSTANCE_PRINCIPA int NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_JONCTION') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_JONCTION datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TYPE_JONCTION') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TYPE_JONCTION varchar(5) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_NUM_REP_GENERAL') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_NUM_REP_GENERAL varchar(10) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_DSJUD') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_DSJUD int NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_AFFRE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_AFFRE int NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_CRNPC') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_CRNPC int NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TOP_EXPERIAN') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TOP_EXPERIAN bit NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_MAJ_INFOG') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_MAJ_INFOG datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_NUMERO_SOURCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_NUMERO_SOURCE varchar(36) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_CALENDRIER') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_CALENDRIER varchar(5) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_DEBUT_CAL') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_DEBUT_CAL datetime NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_NUM_ETAPE_CAL') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_NUM_ETAPE_CAL smallint NULL;
IF OBJECT_ID(N'v2.CODE_AFFAIRE') IS NULL
    CREATE TABLE v2.CODE_AFFAIRE (R_CODEAFFAIR_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_CODEAFFAIR_LIBELLE_ECRAN varchar(100) NOT NULL,
        R_CODEAFFAIR_TYPE_NUM_ROLE varchar(5) NULL, R_CODEAFFAIR_TYPE_INSTANCE varchar(2) NOT NULL);
IF OBJECT_ID(N'v2.NATURE_AFFAIRE') IS NULL
    CREATE TABLE v2.NATURE_AFFAIRE (R_NATUREAFFA_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_NATUREAFFA_LIBELLE_ECRAN varchar(75) NULL);
IF OBJECT_ID(N'v2.TYPE_JONCTION') IS NULL
    CREATE TABLE v2.TYPE_JONCTION (R_TYPEJONCTI_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_TYPEJONCTI_LIBELLE_ECRAN varchar(35) NOT NULL);
IF COL_LENGTH('v2.DEMANDE', 'DMND_EN_COURS') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_EN_COURS bit NULL;
IF COL_LENGTH('v2.DEMANDE', 'DMND_NOM_UTILISATEUR') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_NOM_UTILISATEUR varchar(255) NULL;
IF OBJECT_ID(N'v2.DOSSIER_DEMANDE') IS NULL
    CREATE TABLE v2.DOSSIER_DEMANDE (DSSDM_ID_DSSDM int NOT NULL PRIMARY KEY, DSSDM_ID_DMND int NOT NULL,
        DSSDM_CODE_SEQUENCEUR varchar(20) NOT NULL, DSSDM_VALEUR_SEQUENCEUR varchar(100) NULL);
IF OBJECT_ID(N'v2.ETAT_DEMANDE') IS NULL
    CREATE TABLE v2.ETAT_DEMANDE (R_ETATDEMAND_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_ETATDEMAND_LIBELLE_ECRAN varchar(35) NOT NULL);

-- Les codes du lot 4 (types de numero de role de RIG v2) et deux types de jonction de RIG_DEV (libelles au mot pres).
-- Les instances (date de saisine en 1990, comme leur role : le numero est « conforme », Instance.VerifierCoherenceNumero ; aucune
-- ligne de NUMERO_METIER pour ces types et cette annee) :
--   1400301 XLIEN ALPHA (JRPC) : libre, date de l'acte 01/02/1990 -- la fille des jonctions de PROC_JOIN.gestes ;
--   1400302 XLIEN BETA (JRPC) : rattachee a la PC 1400101, JOINTE a 1400303 ;
--   1400303 XLIEN GAMMA (JRPC) : rattachee a la prevention 1400201, mere de 1400302 ;
--   1400304 XLIEN DELTA (JRPR) : libre, hors des types de « Instance judiciaire » et de « Supprimer une instance » ;
--   1400305 XLIEN EPSILON (JRPC) : tenue par une demande en cours sur 2J ;
--   1400306 XLIEN ZETA (JROP) : jointe a 1400302 (la chaine 1400303, 1400302, 1400306) ;
--   1400307 XLIEN ETA (JROP) : MEME role que 1400306 (le refus « Plusieurs instances »), rattachee a la PC 1400101 ;
--   1400401 JOIN MERE (JRMDE) : la mere des jonctions, date de l'acte 10/01/1990.
EXEC sp_executesql N'
INSERT INTO v2.CODE_AFFAIRE (R_CODEAFFAIR_VALEUR, R_CODEAFFAIR_LIBELLE_ECRAN, R_CODEAFFAIR_TYPE_NUM_ROLE, R_CODEAFFAIR_TYPE_INSTANCE) VALUES
    (''PC14'', ''Contentieux du banc lot 4'', ''JRPC'', ''07''), (''PR14'', ''Prévention du banc lot 4'', ''JRPR'', ''PR''),
    (''OP14'', ''Opposition du banc lot 4'', ''JROP'', ''07''), (''MDE14'', ''Mesure du banc lot 4'', ''JRMDE'', ''07'');
INSERT INTO v2.TYPE_JONCTION (R_TYPEJONCTI_VALEUR, R_TYPEJONCTI_LIBELLE_ECRAN) VALUES (''C'', ''Jonction complète''), (''R'', ''Jonction de rapprochement'');
INSERT INTO v2.INSTANCE (INSTN_ID_INSTN, INSTN_NUM_ROLE, INSTN_NOM_COURANT, INSTN_CODE_AFFAIRE, INSTN_DATE_ACTE, INSTN_DATE_SAISINE_GREFFE,
    INSTN_ID_PRCLL, INSTN_ID_PREVE, INSTN_ID_INSTN_INSTANCE_PRINCIPA, INSTN_DATE_JONCTION, INSTN_TYPE_JONCTION, INSTN_TOP_EXPERIAN) VALUES
    (1400301, ''1990J14301'', ''XLIEN ALPHA'', ''PC14'', ''19900201'', ''19900115'', NULL, NULL, NULL, NULL, NULL, 0),
    (1400302, ''1990J14302'', ''XLIEN BETA'', ''PC14'', NULL, ''19900115'', 1400101, NULL, 1400303, ''19900115'', ''C'', 0),
    (1400303, ''1990J14303'', ''XLIEN GAMMA'', ''PC14'', NULL, ''19900115'', NULL, 1400201, NULL, NULL, NULL, 0),
    (1400304, ''1990R14304'', ''XLIEN DELTA'', ''PR14'', NULL, ''19900115'', NULL, NULL, NULL, NULL, NULL, 0),
    (1400305, ''1990J14305'', ''XLIEN EPSILON'', ''PC14'', NULL, ''19900115'', NULL, NULL, NULL, NULL, NULL, 0),
    (1400306, ''1990J14306'', ''XLIEN ZETA'', ''OP14'', NULL, ''19900115'', NULL, NULL, 1400302, ''19900120'', ''R'', 0),
    (1400307, ''1990J14306'', ''XLIEN ETA'', ''OP14'', NULL, ''19900115'', 1400101, NULL, NULL, NULL, NULL, 0),
    (1400401, ''1990M14401'', ''JOIN MERE'', ''MDE14'', ''19900110'', ''19900110'', NULL, NULL, NULL, NULL, NULL, 0);
INSERT INTO v2.DEMANDE (DMND_ID_DMND, DMND_NUM_DEMANDE, DMND_ETAT_DEMANDE, DMND_CODE_PROSS, DMND_EN_COURS, DMND_NOM_UTILISATEUR) VALUES
    (1400901, ''26014000901'', ''Q'', ''MJUD'', 1, ''M. AUTRE BANC'');
INSERT INTO v2.DOSSIER_DEMANDE (DSSDM_ID_DSSDM, DSSDM_ID_DMND, DSSDM_CODE_SEQUENCEUR, DSSDM_VALEUR_SEQUENCEUR) VALUES
